// packages/shared/src/campus/campus-sites.ts
function normalizeCampusSiteCode(code) {
  return code.trim().toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 20);
}
var campusSiteCodeSchema = external_exports.string().trim().transform((s2) => normalizeCampusSiteCode(s2)).refine((s2) => s2.length >= 2 && s2.length <= 20, {
  message: "Campus code must be 2\u201320 letters or numbers"
});
var campusSiteKindSchema = external_exports.enum([
  "main",
  "regional",
  "medical",
  "research",
  "other"
]);
var campusSiteSchema = external_exports.object({
  code: campusSiteCodeSchema,
  name: external_exports.string().trim().min(1).max(200),
  city: external_exports.string().trim().max(120).optional(),
  state: external_exports.string().trim().max(2).transform((s2) => s2.toUpperCase()).optional(),
  kind: campusSiteKindSchema.optional(),
  active: external_exports.boolean().optional().default(true)
});
var campusBuildingSiteAssignmentSchema = external_exports.object({
  buildingId: external_exports.string().trim().min(1).max(50),
  siteCode: campusSiteCodeSchema
});
var campusSitesPutSchema = external_exports.object({
  sites: external_exports.array(campusSiteSchema).min(1).max(50),
  buildingAssignments: external_exports.array(campusBuildingSiteAssignmentSchema).max(500).optional()
}).strict().superRefine((value, ctx) => {
  const codes = value.sites.map((site) => site.code);
  if (new Set(codes).size !== codes.length) {
    ctx.addIssue({
      code: external_exports.ZodIssueCode.custom,
      message: "Campus codes must be unique",
      path: ["sites"]
    });
  }
  const allowed = new Set(codes);
  for (const [index, assignment] of (value.buildingAssignments ?? []).entries()) {
    if (!allowed.has(assignment.siteCode)) {
      ctx.addIssue({
        code: external_exports.ZodIssueCode.custom,
        message: `Unknown campus ${assignment.siteCode}`,
        path: ["buildingAssignments", index, "siteCode"]
      });
    }
  }
});

