var MARKETING_BLOCKED_EMAIL_DOMAINS = [
  "gmail.com",
  "yahoo.com",
  "hotmail.com",
  "outlook.com",
  "icloud.com",
  "aol.com",
  "protonmail.com",
  "me.com"
];
function isMarketingBusinessEmail(email) {
  const trimmed = email.trim().toLowerCase();
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) return false;
  const domain = trimmed.split("@")[1] ?? "";
  return !MARKETING_BLOCKED_EMAIL_DOMAINS.includes(domain);
}
var marketingLeadBodySchema = external_exports.object({
  firstName: external_exports.string().trim().min(1, "Required").max(100),
  lastName: external_exports.string().trim().min(1, "Required").max(100),
  email: external_exports.string().trim().min(1, "Required").email("Invalid email address").max(320).transform((v) => v.toLowerCase()).refine(isMarketingBusinessEmail, { message: "Please use a business email address" }),
  state: external_exports.string().trim().min(1, "Required").max(100),
  referrer: external_exports.string().max(2e3).nullable().optional(),
  landingPage: external_exports.string().max(500).optional(),
  capturedAt: external_exports.string().max(64).optional(),
  utmSource: external_exports.string().max(200).optional(),
  utmMedium: external_exports.string().max(200).optional(),
  utmCampaign: external_exports.string().max(200).optional(),
  utmContent: external_exports.string().max(200).optional()
}).strict();
